const clean=v=>String(v??'').trim();
const unique=a=>[...new Set(a.map(clean).filter(Boolean))];
export function getMakes(){return unique(vehicleCatalog.map(x=>x.make));}
export function getModels(make){return unique(vehicleCatalog.filter(x=>clean(x.make)===clean(make)).map(x=>x.model));}
export function getYears(make,model){const rows=vehicleCatalog.filter(x=>clean(x.make)===clean(make)&&clean(x.model)===clean(model)); const years=rows.flatMap(x=>x.years?.length?x.years:range(x.year_from,x.year_to)); return unique(years).sort((a,b)=>Number(a)-Number(b));}
export function getVehicleVariants(make,model,year){return vehicleCatalog.filter(x=>clean(x.make)===clean(make)&&clean(x.model)===clean(model)&&(!year||!x.years?.length||x.years.includes(Number(year)))).map(x=>({generation:x.generation??null,body:x.body??null,engine:x.engines??[],fuel:x.fuels??[],transmission:x.transmissions??[],trim:x.trims??[]}));}
export function optionsFor(selection,field){if(field==='type')return unique(vehicleCatalog.filter(x=>!selection.type||x.type===selection.type).map(x=>x.type)).sort((a,b)=>a.localeCompare(b,'tr'));if(field==='make')return unique(vehicleCatalog.filter(x=>!selection.type||x.type===selection.type).map(x=>x.make)).sort((a,b)=>a.localeCompare(b,'tr'));if(field==='model')return getModels(selection.make);if(field==='year')return getYears(selection.make,selection.model).map(String);if(field==='engine'){return unique(getVehicleVariants(selection.make,selection.model,selection.year).flatMap(x=>[...x.engine,...x.trim])).sort((a,b)=>a.localeCompare(b,'tr'));}return [];}
function range(a,b){const out=[];if(!Number.isFinite(Number(a)))return out;for(let y=Number(a);y<=Number(b||a);y++)out.push(y);return out;}
